import { test, expect } from '@playwright/test';

test.describe('Mobile Hamburger Menu', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should open the hamburger menu when clicked', async ({ page }) => {
    const hamburgerMenu = page.getByRole('button', { name: /menu/i });
    await hamburgerMenu.click();

    const menu = page.getByRole('navigation');
    await expect(menu).toBeVisible();
  });

  test('should close the hamburger menu when clicked again', async ({ page }) => {
    const hamburgerMenu = page.getByRole('button', { name: /menu/i });
    await hamburgerMenu.click(); // Open the menu
    await hamburgerMenu.click(); // Close the menu

    const menu = page.getByRole('navigation');
    await expect(menu).not.toBeVisible();
  });
});
